  "journey.planTitle": { en: "Plan a Safe Journey", hi: "एक सुरक्षित यात्रा की योजना बनाएं", bn: "একটি নিরাপদ যাত্রা পরিকল্পনা করুন", ta: "பாதுகாப்பான பயணத்தைத் திட்டமிடுங்கள்", te: "సురక్షిత ప్రయాణాన్ని ప్లాన్ చేయండి", mr: "सुरक्षित प्रवासाची योजना करा" },
  "journey.planDesc": { en: "Choose where you're headed — Suraksha360 scores the route before you start.", hi: "चुनें कि आप कहाँ जा रहे हैं — सुरक्षा360 शुरू करने से पहले मार्ग को स्कोर करता है।", bn: "আপনি কোথায় যাচ্ছেন তা বেছে নিন — সুরক্ষা৩৬০ শুরু করার আগে রুট স্কোর করে।", ta: "நீங்கள் செல்லும் இடத்தைத் தேர்வு செய்யுங்கள் — நீங்கள் தொடங்குவதற்கு முன் சுரக்ஷா360 பாதையை மதிப்பிடுகிறது.", te: "మీరు ఎక్కడికి వెళుతున్నారో ఎంచుకోండి — మీరు ప్రారంభించే ముందు సురక్ష360 మార్గాన్ని స్కోర్ చేస్తుంది.", mr: "तुम्ही कुठे जात आहात ते निवडा — तुम्ही सुरुवात करण्यापूर्वी सुरक्षा360 मार्गाला गुण देते." },
  "journey.destination": { en: "Destination", hi: "गंतव्य", bn: "গন্তব্য", ta: "இலக்கு", te: "గమ్యం", mr: "गंतव्यस्थान" },
  "journey.liveGpsOn": { en: "Live GPS on", hi: "लाइव जीपीएस चालू है", bn: "লাইভ জিপিএস চালু আছে", ta: "நேரடி GPS இயக்கத்தில் உள்ளது", te: "ప్రత్యక్ష GPS ఆన్‌లో ఉంది", mr: "थेट जीपीएस सुरू आहे" },
