  "journey.searchPlaceholder": { en: "Search for an address, station, or landmark", hi: "पता, स्टेशन या स्थलचिह्न खोजें", bn: "একটি ঠিকানা, স্টেশন বা ল্যান্ডমার্ক খুঁজুন", ta: "முகவரி, நிலையம் அல்லது சின்னச்சின்னத்தைத் தேடுங்கள்", te: "చిరునామా, స్టేషన్ లేదా ల్యాండ్‌మార్క్ కోసం వెతకండి", mr: "पत्ता, स्टेशन किंवा खूण शोधा" },
  "journey.searching": { en: "Searching…", hi: "खोज रहे हैं…", bn: "খুঁজছে…", ta: "தேடுகிறது…", te: "వెతుకుతోంది…", mr: "शोधत आहे…" },
  "journey.shareLocationHint": { en: "Tap the location icon to share your current position as the starting point.", hi: "अपनी वर्तमान स्थिति को प्रारंभिक बिंदु के रूप में साझा करने के लिए लोकेशन आइकन पर टैप करें।", bn: "আপনার বর্তমান অবস্থানকে শুরুর বিন্দু হিসেবে শেয়ার করতে লোকেশন আইকনে ট্যাপ করুন।", ta: "உங்கள் தற்போதைய இருப்பிடத்தை தொடக்கப் புள்ளியாகப் பகிர இருப்பிட ஐகானைத் தட்டவும்.", te: "మీ ప్రస్తుత స్థానాన్ని ప్రారంభ బిందువుగా పంచుకోవడానికి లొకేషన్ ఐకాన్‌ను నొక్కండి.", mr: "तुमचे सध्याचे स्थान सुरुवातीचा बिंदू म्हणून शेअर करण्यासाठी लोकेशन आयकॉनवर टॅप करा." },
  "journey.searchUnavailable": { en: "Search is temporarily unavailable — try again in a moment.", hi: "खोज अस्थायी रूप से अनुपलब्ध है — कुछ देर में फिर से प्रयास करें।", bn: "অনুসন্ধান সাময়িকভাবে অনুপলব্ধ — একটু পরে আবার চেষ্টা করুন।", ta: "தேடல் தற்காலிகமாகக் கிடைக்கவில்லை — சிறிது நேரம் கழித்து மீண்டும் முயற்சிக்கவும்.", te: "శోధన తాత్కాలికంగా అందుబాటులో లేదు — కొద్దిసేపటిలో మళ్లీ ప్రయత్నించండి.", mr: "शोध तात्पुरता अनुपलब्ध आहे — थोड्या वेळाने पुन्हा प्रयत्न करा." },
  "journey.nearbySuggestions": { en: "Nearby suggestions", hi: "आस-पास के सुझाव", bn: "কাছাকাছি পরামর্শ", ta: "அருகிலுள்ள பரிந்துரைகள்", te: "సమీప సూచనలు", mr: "जवळपासच्या सूचना" },
